const rulesSource="// Chess rules v1: deterministic, no network or account state. 0x88 board.\nexport const START_FEN='rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';\nconst dirs={n:[-33,-31,-18,-14,14,18,31,33],b:[-17,-15,15,17],r:[-16,-1,1,16],k:[-17,-16,-15,-1,1,15,16,17]};\nconst active=i=>i>=0&&i<128&&!(i&0x88);\nconst color=p=>p==='.'?0:p===p.toUpperCase()?1:-1;\nexport const coord=i=>'abcdefgh'[i&7]+(8-(i>>4));\nexport const square=s=>/^[a-h][1-8]$/.test(s)?(8-Number(s[1]))*16+'abcdefgh'.indexOf(s[0]):-1;\nexport function parseFen(fen=START_FEN){\n const [placement,turn,castling,ep,half,full]=fen.split(' ');\n if(!placement||!/^[wb]$/.test(turn)||!/^(?:-|K?Q?k?q?)$/.test(castling)||!/^(?:-|[a-h][36])$/.test(ep)||!/^\\d+$/.test(half)||!/^[1-9]\\d*$/.test(full))throw Error('INVALID_FEN');\n const b=Array(128).fill('.'),rows=placement.split('/');\n if(rows.length!==8)throw Error('INVALID_FEN');\n for(let r=0;r<8;r++){\n  let c=0;\n  for(const p of rows[r]){\n   if(/^[1-8]$/.test(p))c+=Number(p);\n   else{if(!/^[pnbrqkPNBRQK]$/.test(p)||c>=8)throw Error('INVALID_FEN');b[r*16+c++]=p;}\n  }\n  if(c!==8)throw Error('INVALID_FEN');\n }\n if(b.filter(x=>x==='K').length!==1||b.filter(x=>x==='k').length!==1)throw Error('INVALID_KINGS');\n return {b,t:turn==='w'?1:-1,c:(castling.includes('K')?1:0)|(castling.includes('Q')?2:0)|(castling.includes('k')?4:0)|(castling.includes('q')?8:0),ep:ep==='-'?-1:square(ep),half:Number(half),full:Number(full)};\n}\nexport const initial=()=>parseFen();\nexport function attacked(s,target,by){\n for(let from=0;from<128;from++){\n  if(!active(from)||color(s.b[from])!==by)continue;\n  const piece=s.b[from].toLowerCase();\n  if(piece==='p'){if(target===from-16*by-1||target===from-16*by+1)return true;continue;}\n  for(const d of (dirs[piece]||[...dirs.b,...dirs.r])){\n   for(let to=from+d;active(to);to+=d){\n    if(to===target)return true;\n    if(s.b[to]!=='.'||piece==='n'||piece==='k')break;\n   }\n  }\n }\n return false;\n}\nexport const check=(s,by=s.t)=>attacked(s,s.b.indexOf(by===1?'K':'k'),-by);\nexport function apply(s,m){\n const [from,to,promotion,flag]=m,b=s.b.slice(),piece=b[from],captured=b[to];let c=s.c;\n b[from]='.';b[to]=promotion?(s.t===1?promotion.toUpperCase():promotion):piece;\n if(flag==='ep')b[to+16*s.t]='.';\n if(flag==='castle'){const rf=to>from?from+3:from-4,rt=to>from?from+1:from-1;b[rt]=b[rf];b[rf]='.';}\n if(piece==='K')c&=~3;if(piece==='k')c&=~12;\n const rooks={119:1,112:2,7:4,0:8};\n if(piece.toLowerCase()==='r')c&=~(rooks[from]||0);\n if(captured.toLowerCase()==='r')c&=~(rooks[to]||0);\n return {b,t:-s.t,c,ep:piece.toLowerCase()==='p'&&Math.abs(to-from)===32?(to+from)/2:-1,\n half:piece.toLowerCase()==='p'||captured!=='.'||flag==='ep'?0:s.half+1,full:s.full+(s.t===-1?1:0)};\n}\nexport function legal(s){\n const out=[],turn=s.t;\n for(let from=0;from<128;from++){\n  if(!active(from)||color(s.b[from])!==turn)continue;\n  const p=s.b[from].toLowerCase();\n  const add=(to,flag='')=>{\n   if(s.b[to].toLowerCase()==='k')return;\n   if(p==='p'&&((to>>4)===0||(to>>4)===7))for(const promote of ['q','r','b','n'])out.push([from,to,promote,flag]);\n   else out.push([from,to,'',flag]);\n  };\n  if(p==='p'){\n   const to=from-16*turn;\n   if(active(to)&&s.b[to]==='.'){\n    add(to);\n    const two=to-16*turn;\n    if((from>>4)===(turn===1?6:1)&&s.b[two]==='.')add(two);\n   }\n   for(const dx of [-1,1]){\n    const t=to+dx;if(!active(t))continue;\n    if(color(s.b[t])===-turn)add(t);\n    else if(t===s.ep&&s.b[t]==='.'&&s.b[t+16*turn]===(turn===1?'p':'P'))add(t,'ep');\n   }\n  }else{\n   const directions=p==='q'?[...dirs.b,...dirs.r]:dirs[p];\n   for(const d of directions)for(let to=from+d;active(to);to+=d){\n    if(color(s.b[to])===turn)break;add(to);\n    if(s.b[to]!=='.'||p==='n'||p==='k')break;\n   }\n   if(p==='k'&&from===(turn===1?116:4)&&!check(s)){\n    const rook=turn===1?'R':'r',rights=turn===1?[1,2]:[4,8];\n    if((s.c&rights[0])&&s.b[from+3]===rook&&s.b[from+1]==='.'&&s.b[from+2]==='.'&&!attacked(s,from+1,-turn)&&!attacked(s,from+2,-turn))add(from+2,'castle');\n    if((s.c&rights[1])&&s.b[from-4]===rook&&s.b[from-1]==='.'&&s.b[from-2]==='.'&&s.b[from-3]==='.'&&!attacked(s,from-1,-turn)&&!attacked(s,from-2,-turn))add(from-2,'castle');\n   }\n  }\n }\n return out.filter(m=>!check(apply(s,m),turn));\n}\nexport function move(s,uci){\n if(typeof uci!=='string'||!/^[a-h][1-8][a-h][1-8][qrbn]?$/.test(uci))return null;\n const m=legal(s).find(x=>coord(x[0])+coord(x[1])+x[2]===uci);\n return m?apply(s,m):null;\n}\nexport function san(s,m){\n const [from,to,promotion,flag]=m,p=s.b[from].toUpperCase(),capture=s.b[to]!=='.'||flag==='ep';\n let text='';\n if(flag==='castle')text=to>from?'O-O':'O-O-O';\n else{\n  if(p!=='P'){\n   text=p;\n   const others=legal(s).filter(x=>x[0]!==from&&x[1]===to&&s.b[x[0]]===s.b[from]);\n   if(others.length)text+=!others.some(x=>(x[0]&7)===(from&7))?coord(from)[0]:!others.some(x=>(x[0]>>4)===(from>>4))?coord(from)[1]:coord(from);\n  }else if(capture)text=coord(from)[0];\n  text+=(capture?'x':'')+coord(to)+(promotion?'='+promotion.toUpperCase():'');\n }\n const next=apply(s,m);\n return text+(check(next)?legal(next).length?'+':'#':'');\n}\nexport function key(s){\n // Repetition rights include en passant only when an actual *legal* capture exists.\n // A phantom or king-pinned en passant square does not distinguish FIDE positions.\n const ep=s.ep>=0&&legal(s).some(m=>m[3]==='ep')?s.ep:-1;\n return s.b.join('')+':'+s.t+':'+s.c+':'+ep;\n}\nexport function claimableDraw(s,positions=[]){\n if(s.half>=100)return '50_RUCHOW';\n if(Array.isArray(positions)&&positions.filter(position=>position===key(s)).length>=3)\n  return 'TRZYKROTNE_POWTORZENIE';\n return '';\n}\nexport function result(states){\n const s=states[states.length-1],moves=legal(s);\n if(!moves.length)return check(s)?(s.t===1?'Mat — czarne wygrywają':'Mat — białe wygrywają'):'Pat — remis';\n const units=[];for(let i=0;i<128;i++)if(active(i)&&s.b[i]!=='.'&&!/[kK]/.test(s.b[i]))units.push([s.b[i].toLowerCase(),((i>>4)+(i&7))%2]);\n if(!units.length||(units.length===1&&['b','n'].includes(units[0][0]))||(units.every(x=>x[0]==='b')&&new Set(units.map(x=>x[1])).size===1))return 'Remis — brak materiału matującego';\n if(s.half>=150)return 'Remis — 75 ruchów';\n if(states.filter(x=>key(x)===key(s)).length>=5)return 'Remis — pięciokrotne powtórzenie';\n return '';\n}\n";
const computerSource="// Deterministic, bounded computer opponent. Uses the same legal rules as the server.\n// This is a lightweight local engine, not Stockfish or grandmaster-strength AI.\nimport {legal,apply,check} from '/konto/szachy/rules.mjs';\nconst values={p:100,n:320,b:330,r:500,q:900,k:0};\nfunction score(state){\n let value=0;\n for(let i=0;i<128;i++){\n  if(i&0x88){i=(i|7);continue;}\n  const p=state.b[i];if(p==='.')continue;\n  const own=p===p.toUpperCase()?1:-1,type=p.toLowerCase();\n  const col=i&7,row=i>>4,center=(3.5-Math.abs(col-3.5))+(3.5-Math.abs(row-3.5));\n  let v=values[type];\n  if(type==='p')v+=own===1?(6-row)*8:(row-1)*8;\n  if(type==='n'||type==='b')v+=center*7;\n  if(type==='k'&&state.full<25)v-=center*3;\n  value+=own*v;\n }\n return value;\n}\nfunction movePriority(s,m){\n const victim=s.b[m[1]];const attacker=s.b[m[0]];\n return (victim==='.'?0:10*(values[victim.toLowerCase()]||0)-(values[attacker.toLowerCase()]||0))+(m[2]?800:0)+(m[3]==='castle'?20:0);\n}\nexport function chooseComputerMove(state,{level='normal',maxMs=650}={}){\n if(!state||!Array.isArray(state.b)||![1,-1].includes(state.t))return null;\n const candidates=legal(state);if(!candidates.length)return null;\n const caps=Math.max(100,Math.min(1300,Number(maxMs)||650));\n const deadline=Date.now()+caps;\n const maximum={beginner:1,normal:2,hard:3,master:4}[level]||2;\n let best=candidates[0],completed=false,nodes=0;\n const ordered=(s,moves)=>moves.sort((a,b)=>movePriority(s,b)-movePriority(s,a));\n const terminal=(s,moves,ply)=>moves.length?null:check(s)?-100000+ply:0;\n function search(s,depth,alpha,beta,ply){\n  if(++nodes%32===0&&Date.now()>deadline)throw Error('TIME_BUDGET');\n  const moves=legal(s),end=terminal(s,moves,ply);\n  if(end!==null)return end;\n  if(!depth)return score(s)*s.t;\n  let value=-Infinity;\n  for(const m of ordered(s,moves)){\n   const v=-search(apply(s,m),depth-1,-beta,-alpha,ply+1);\n   if(v>value)value=v;\n   if(v>alpha)alpha=v;\n   if(alpha>=beta)break;\n  }\n  return value;\n }\n for(let depth=1;depth<=maximum;depth++){\n  let highest=-Infinity,next=best;\n  try{\n   for(const m of ordered(state,candidates.slice())){\n    if(Date.now()>deadline)throw Error('TIME_BUDGET');\n    const v=-search(apply(state,m),depth-1,-Infinity,-highest,1);\n    if(v>highest){highest=v;next=m;}\n   }\n   best=next;completed=true;\n  }catch(e){if(e.message!=='TIME_BUDGET')throw e;break;}\n }\n return best;\n}\n";
// CHESS-TRANSFER-P1: browser copy of auth/chess-transfer.mjs (only the rules import path differs; test-enforced).
const transferSource="// Pure PGN/FEN transfer for chess. The server tests and the browser console share this exact file.\n// Import only builds a validated local position and move list; it never updates a live online match.\nimport {START_FEN,parseFen,legal,apply,coord,square,san,check,result} from '/konto/szachy/rules.mjs';\nexport const MAX_PGN=200_000,MAX_PLIES=2_000;\nconst MAX_FEN=120,MAX_TAGS=64,MAX_TAG_VALUE=1_000;\nconst UCI=/^[a-h][1-8][a-h][1-8][qrbn]?$/;\nconst RESULTS=new Set(['1-0','0-1','1/2-1/2','*']);\nconst RESERVED=new Set(['Result','FEN','SetUp']);\nconst TAG_NAME=/^[A-Za-z][A-Za-z0-9_]*$/;\n// Short algebraic (SAN) plus the long forms other programs export: Ng1-f3, e2e4, e7e8q, 0-0.\nconst SAN=/^(?:(O-O-O|O-O)|([NBRQKP])?([a-h])?([1-8])?([-x:])?([a-h][1-8])(?:=?([NBRQnbrq]))?)$/;\nconst fail=(code,detail={})=>Object.assign(Error(code),{code},detail);\nfunction assertText(value,max){if(typeof value!=='string'||value.length>max)throw fail('CHESS_TRANSFER_SIZE');return value;}\nconst moveKey=m=>coord(m[0])+coord(m[1])+m[2];\n// Automatic end of the game according to the shared rules engine, as a PGN result ('' = game continues).\nexport function terminalOutcome(states){\n const text=result(states);\n return !text?'':/białe wygrywają/.test(text)?'1-0':/czarne wygrywają/.test(text)?'0-1':'1/2-1/2';\n}\nexport function exportFen(s){\n if(!s||!Array.isArray(s.b)||s.b.length!==128||![1,-1].includes(s.t)||!Number.isInteger(s.c)||s.c<0||s.c>15||\n    !Number.isInteger(s.ep)||s.ep< -1||s.ep>=128||(s.ep>=0&&(s.ep&0x88))||\n    !Number.isSafeInteger(s.half)||s.half<0||!Number.isSafeInteger(s.full)||s.full<1)throw fail('INVALID_POSITION');\n const rows=[];\n for(let r=0;r<8;r++){\n  let row='',empty=0;\n  for(let f=0;f<8;f++){\n   const p=s.b[r*16+f];\n   if(p==='.'){empty++;continue;}\n   if(typeof p!=='string'||!/^[pnbrqkPNBRQK]$/.test(p))throw fail('INVALID_POSITION');\n   if(empty)row+=empty;empty=0;row+=p;\n  }\n  if(empty)row+=empty;rows.push(row);\n }\n const castling=(s.c&1?'K':'')+(s.c&2?'Q':'')+(s.c&4?'k':'')+(s.c&8?'q':'')||'-';\n return rows.join('/')+' '+(s.t===1?'w':'b')+' '+castling+' '+(s.ep<0?'-':coord(s.ep))+' '+s.half+' '+s.full;\n}\nexport function importFen(text){\n const fields=assertText(text,MAX_FEN).trim().split(/\\s+/);\n if(fields.length===4)fields.push('0','1'); // EPD-style FEN without counters\n if(fields.length!==6)throw fail('INVALID_FEN');\n const fen=fields.join(' ');\n let state;\n try{state=parseFen(fen);}catch(error){throw fail(error.message==='INVALID_KINGS'?'INVALID_FEN_KINGS':'INVALID_FEN');}\n if(exportFen(state)!==fen)throw fail('INVALID_FEN');\n const b=state.b,t=state.t,ep=state.ep;\n for(let f=0;f<8;f++)if(/[Pp]/.test(b[f])||/[Pp]/.test(b[112+f]))throw fail('INVALID_FEN_PAWN');\n for(const side of [/^[PNBRQK]$/,/^[pnbrqk]$/]){\n  const own=b.filter(p=>side.test(p));\n  if(own.length>16||own.filter(p=>p==='P'||p==='p').length>8)throw fail('INVALID_FEN_MATERIAL');\n }\n if((state.c&1)&&(b[116]!=='K'||b[119]!=='R')||(state.c&2)&&(b[116]!=='K'||b[112]!=='R')||\n    (state.c&4)&&(b[4]!=='k'||b[7]!=='r')||(state.c&8)&&(b[4]!=='k'||b[0]!=='r'))throw fail('INVALID_FEN_CASTLING');\n // The en passant square must sit behind a pawn that has just made a double step.\n if(ep>=0&&((ep>>4)!==(t===1?2:5)||b[ep]!=='.'||b[ep-16*t]!=='.'||b[ep+16*t]!==(t===1?'p':'P')))throw fail('INVALID_FEN_EN_PASSANT');\n // The side that has just moved can never be left in check.\n if(check(state,-t))throw fail('INVALID_FEN_CHECK');\n return state;\n}\n// First game only: tags, then main-line tokens. Comments, NAGs, % escapes and variations are skipped.\nfunction readPgn(input){\n const text=input.replace(/^\\uFEFF/,'').replace(/\\r\\n?/g,'\\n');\n const tags=Object.create(null),tokens=[],tag=/\\[[ \\t]*([A-Za-z][A-Za-z0-9_]*)[ \\t]+\"((?:\\\\.|[^\"\\\\\\n])*)\"[ \\t]*\\]/y;\n let i=0,count=0,depth=0,outcome='';\n const lineEnd=from=>{const end=text.indexOf('\\n',from);return end<0?text.length:end;};\n for(;;){\n  while(i<text.length&&/\\s/.test(text[i]))i++;\n  if(text[i]==='%'&&(i===0||text[i-1]==='\\n')){i=lineEnd(i);continue;}\n  if(text[i]!=='[')break;\n  tag.lastIndex=i;const m=tag.exec(text);\n  if(!m||++count>MAX_TAGS||m[2].length>MAX_TAG_VALUE)throw fail('INVALID_PGN_TAG');\n  tags[m[1]]=m[2].replace(/\\\\([\"\\\\])/g,'$1');i=tag.lastIndex;\n }\n while(i<text.length){\n  const ch=text[i];\n  if(/\\s/.test(ch)){i++;continue;}\n  if(ch==='%'&&(i===0||text[i-1]==='\\n')){i=lineEnd(i);continue;}\n  if(ch===';'){i=lineEnd(i);continue;}\n  if(ch==='{'){const end=text.indexOf('}',i);if(end<0)throw fail('INVALID_PGN_COMMENT');i=end+1;continue;}\n  if(ch==='('){depth++;i++;continue;}\n  if(ch===')'){if(!depth)throw fail('INVALID_PGN_VARIATION');depth--;i++;continue;}\n  if(ch==='['&&!depth)break; // the next game starts without a termination marker\n  if(ch==='['||ch===']'||ch==='}')throw fail('INVALID_PGN_TOKEN');\n  let end=i;while(end<text.length&&!/[\\s{}();[\\]]/.test(text[end]))end++;\n  const word=text.slice(i,end);i=end;\n  if(depth)continue;\n  if(RESULTS.has(word)){outcome=word;break;}\n  const move=word.replace(/^\\d+\\.+/,''); // move numbers \"12.\" and \"12...\" (never castling \"0-0\")\n  if(!move||/^\\d+$/.test(move)||/^\\$\\d+$/.test(move)||/^[!?]+$/.test(move)||move==='e.p.')continue;\n  if(tokens.length>=MAX_PLIES)throw fail('CHESS_TRANSFER_SIZE');\n  tokens.push(move);\n }\n if(depth)throw fail('INVALID_PGN_VARIATION');\n return {tags,tokens,outcome};\n}\n// Every legal move the token can describe. Exactly one match is required by the caller.\nfunction matchMoves(s,token){\n const m=SAN.exec(token.replace(/e\\.p\\.$/,'').replace(/[+#!?]+$/,'').replace(/0/g,'O'));\n if(!m)return [];\n const [,castle,piece,file,rank,separator,target,promotion]=m,moves=legal(s);\n if(castle)return moves.filter(x=>x[3]==='castle'&&(x[1]>x[0])===(castle==='O-O'));\n const to=square(target),capture=separator==='x'||separator===':',long=!piece&&file&&rank;\n return moves.filter(x=>x[1]===to&&\n  (long?x[0]===square(file+rank):s.b[x[0]].toUpperCase()===(piece||'P'))&&\n  (!file||coord(x[0])[0]===file)&&(!rank||coord(x[0])[1]===rank)&&\n  (!capture||s.b[x[1]]!=='.'||x[3]==='ep')&&\n  (promotion||'').toLowerCase()===x[2]);\n}\nexport function exportPgn(uciMoves,{headers={},startFen=START_FEN,outcome='*'}={}){\n if(!Array.isArray(uciMoves)||uciMoves.length>MAX_PLIES||!RESULTS.has(outcome)||!headers||typeof headers!=='object')throw fail('INVALID_PGN');\n const start=importFen(startFen),fen=exportFen(start),words=[],states=[start];\n let s=start;\n for(const uci of uciMoves){\n  if(typeof uci!=='string'||!UCI.test(uci))throw fail('INVALID_PGN_MOVE');\n  const m=legal(s).find(x=>moveKey(x)===uci);if(!m)throw fail('ILLEGAL_PGN_MOVE');\n  if(s.t===1)words.push(s.full+'.');else if(!words.length)words.push(s.full+'...');\n  words.push(san(s,m));s=apply(s,m);states.push(s);\n }\n const actual=terminalOutcome(states);\n if(actual&&outcome!==actual)throw fail('PGN_RESULT_MISMATCH');\n // Seven Tag Roster first, in the order required by the PGN standard.\n const tags={Event:'GRACZ.PL Szachy',Site:'gracz.pl',Date:'????.??.??',Round:'-',White:'?',Black:'?',Result:outcome};\n for(const [k,v] of Object.entries(headers)){\n  if(!TAG_NAME.test(k)||typeof v!=='string'||v.length>250||/[\\u0000-\\u001f\\u007f]/.test(v))throw fail('INVALID_PGN_TAG');\n  if(RESERVED.has(k))throw fail('RESERVED_PGN_TAG');\n  tags[k]=v;\n }\n if(fen!==START_FEN){tags.SetUp='1';tags.FEN=fen;}\n const lines=[];let line='';\n for(const word of [...words,outcome]){\n  if(line&&line.length+1+word.length>80){lines.push(line);line=word;}else line=line?line+' '+word:word;\n }\n lines.push(line);\n return Object.entries(tags).map(([k,v])=>'['+k+' \"'+v.replaceAll('\\\\','\\\\\\\\').replaceAll('\"','\\\\\"')+'\"]').join('\\n')+'\\n\\n'+lines.join('\\n')+'\\n';\n}\nexport function importPgn(text){\n const {tags,tokens,outcome:marker}=readPgn(assertText(text,MAX_PGN));\n const declared=tags.Result;\n if(declared!==undefined&&!RESULTS.has(declared))throw fail('INVALID_PGN_RESULT');\n if(marker&&declared&&declared!==marker)throw fail('PGN_RESULT_MISMATCH');\n if(tags.SetUp!==undefined&&!['0','1'].includes(tags.SetUp)||tags.SetUp==='1'&&!tags.FEN||tags.SetUp==='0'&&tags.FEN!==undefined)throw fail('INVALID_PGN_SETUP');\n const start=importFen(tags.FEN??START_FEN),states=[start],uciMoves=[],sanMoves=[];\n let s=start,outcome=marker||declared||'*';\n for(const [index,token] of tokens.entries()){\n  const found=matchMoves(s,token);\n  if(found.length!==1)throw fail('ILLEGAL_OR_AMBIGUOUS_PGN_MOVE',{ply:index+1,token,ambiguous:found.length>1});\n  const m=found[0];uciMoves.push(moveKey(m));sanMoves.push(san(s,m));s=apply(s,m);states.push(s);\n }\n const actual=terminalOutcome(states);\n if(actual){if(outcome==='*')outcome=actual;else if(outcome!==actual)throw fail('PGN_RESULT_MISMATCH');}\n return {headers:{...tags},startFen:exportFen(start),uciMoves,sanMoves,outcome,finalFen:exportFen(s),states};\n}\n// Console entry point: one FEN line or one PGN game (the first game of a multi-game file).\nexport function importChessText(text){\n const input=assertText(text,MAX_PGN).replace(/^\\uFEFF/,'').trim();\n if(!input)throw fail('EMPTY_CHESS_TRANSFER');\n if(/^[pnbrqkPNBRQK1-8]+(?:\\/[pnbrqkPNBRQK1-8]+){7}\\s+[wb](?:\\s|$)/.test(input)){\n  const state=importFen(input),fen=exportFen(state);\n  return {kind:'fen',headers:{},startFen:fen,uciMoves:[],sanMoves:[],outcome:terminalOutcome([state])||'*',finalFen:fen,states:[state]};\n }\n return {kind:'pgn',...importPgn(input)};\n}\n";
const realtimeClientSource='export '+createGomokuRealtimeClient.toString()+';\n';
